solution.solution.c:
#include <stdbool.h>
#include <stdlib.h>

struct int_list {
    int *items;
    size_t length;
    size_t capacity;
};

void list_init(struct int_list *list)
{
    list->items = NULL;
    list->length = 0;
    list->capacity = 0;
}

bool list_push(struct int_list *list, int value)
{
    if (list->length == list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        int *bigger = realloc(list->items, new_capacity * sizeof *bigger);
        if (bigger == NULL) return false;
        list->items = bigger;
        list->capacity = new_capacity;
    }
    list->items[list->length++] = value;
    return true;
}

bool list_pop(struct int_list *list, int *out)
{
    if (list->length == 0) return false;
    *out = list->items[--list->length];
    return true;
}

long long list_sum(const struct int_list *list)
{
    long long total = 0;
    for (size_t i = 0; i < list->length; i++) {
        total += list->items[i];
    }
    return total;
}

void list_free(struct int_list *list)
{
    free(list->items);
    list_init(list);
}

unitTests:
TEST("starting empty") { struct int_list l; l.length = 99; list_init(&l); CHECK_EQ(l.length, (size_t)0); CHECK_EQ(l.capacity, (size_t)0); CHECK(l.items == NULL); CHECK_EQ(list_sum(&l), 0LL); list_free(&l); }
TEST("pushing and growing") { struct int_list l; list_init(&l); CHECK(list_push(&l, 10)); CHECK_EQ(l.capacity, (size_t)4); for (int i = 0; i < 4; i++) list_push(&l, i); CHECK_EQ(l.length, (size_t)5); CHECK_EQ(l.capacity, (size_t)8); CHECK_EQ(l.items[0], 10); CHECK_EQ(l.items[4], 3); list_free(&l); }
TEST("thousands of values") { struct int_list l; list_init(&l); for (int i = 1; i <= 10000; i++) { if (!list_push(&l, i)) break; } CHECK_EQ(l.length, (size_t)10000); CHECK_EQ(l.capacity, (size_t)16384); CHECK_EQ(list_sum(&l), 50005000LL); list_free(&l); CHECK_EQ(l.length, (size_t)0); CHECK(l.items == NULL); }
TEST("popping") { struct int_list l; list_init(&l); int v = 0; CHECK(!list_pop(&l, &v)); list_push(&l, 1); list_push(&l, 2); CHECK(list_pop(&l, &v)); CHECK_EQ(v, 2); CHECK(list_pop(&l, &v)); CHECK_EQ(v, 1); CHECK(!list_pop(&l, &v)); CHECK_EQ(v, 1); list_push(&l, 7); CHECK_EQ(l.items[0], 7); list_free(&l); }

